function normalize_sale_datetime(string $value): string { if ($value === '') { return date('Y-m-d H:i:s'); } $dt = DateTime::createFromFormat('Y-m-d\TH:i', $value) ?: DateTime::createFromFormat('Y-m-d H:i:s', $value) ?: DateTime::createFromFormat('Y-m-d H:i', $value); if (!$dt) { throw new RuntimeException('Fecha de venta invalida.'); } return $dt->format('Y-m-d H:i:s'); }
