function upload_product_image(string $current = ''): string {
    if (!isset($_FILES['product_image']) || ($_FILES['product_image']['error'] ?? UPLOAD_ERR_NO_FILE) === UPLOAD_ERR_NO_FILE) {
        return $current;
    }
    if ($_FILES['product_image']['error'] !== UPLOAD_ERR_OK) {
        throw new RuntimeException('No se pudo cargar la imagen del producto.');
    }
    if ($_FILES['product_image']['size'] > 5 * 1024 * 1024) {
        throw new RuntimeException('La imagen no debe superar 5 MB.');
    }
    $info = getimagesize($_FILES['product_image']['tmp_name']);
    if (!$info) {
        throw new RuntimeException('El archivo cargado no es una imagen valida.');
    }
    $allowed = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];
    $mime = $info['mime'] ?? '';
    if (!in_array($mime, $allowed, true)) {
        throw new RuntimeException('Formato de imagen no permitido. Usa JPG, PNG, WEBP o GIF.');
    }
    $sourceData = file_get_contents($_FILES['product_image']['tmp_name']);
    $source = imagecreatefromstring($sourceData);
    if (!$source) {
        throw new RuntimeException('No se pudo procesar la imagen.');
    }
    $srcW = imagesx($source);
    $srcH = imagesy($source);
    $side = min($srcW, $srcH);
    $srcX = (int)(($srcW - $side) / 2);
    $srcY = (int)(($srcH - $side) / 2);
    $size = 320;
    $thumb = imagecreatetruecolor($size, $size);
    $bg = imagecolorallocate($thumb, 255, 247, 237);
    imagefill($thumb, 0, 0, $bg);
    imagecopyresampled($thumb, $source, 0, 0, $srcX, $srcY, $size, $size, $side, $side);
    $dir = __DIR__ . '/uploads/products';
    if (!is_dir($dir)) { mkdir($dir, 0775, true); }
    $filename = 'product-icon-' . date('YmdHis') . '-' . bin2hex(random_bytes(4)) . '.jpg';
    $target = $dir . '/' . $filename;
    if (!imagejpeg($thumb, $target, 86)) {
        imagedestroy($source);
        imagedestroy($thumb);
        throw new RuntimeException('No se pudo guardar el icono del producto.');
    }
    imagedestroy($source);
    imagedestroy($thumb);
    if ($current && str_starts_with($current, 'uploads/products/') && is_file(__DIR__ . '/' . $current)) {
        @unlink(__DIR__ . '/' . $current);
    }
    return 'uploads/products/' . $filename;
}
