$products=db()->query('SELECT * FROM products ORDER BY active DESC, sort_order, name')->fetchAll(); $editingProduct=null; if($route==='products' && isset($_GET['edit'])){ $editStmt=db()->prepare('SELECT * FROM products WHERE id=?'); $editStmt->execute([(int)$_GET['edit']]); $editingProduct=$editStmt->fetch() ?: null; } $activeProducts=array_values(array_filter($products, fn($p)=>(int)$p['active']===1)); $activeAddons=db()->query('SELECT * FROM product_addons WHERE active=1 ORDER BY sort_order, category, name')->fetchAll(); $expenseCategories=db()->query('SELECT * FROM expense_categories ORDER BY active DESC, sort_order, name')->fetchAll(); $purchaseCategories=db()->query('SELECT * FROM purchase_categories ORDER BY active DESC, sort_order, name')->fetchAll(); $suppliers=db()->query('SELECT * FROM suppliers ORDER BY active DESC, sort_order, name')->fetchAll(); $diningTables=db()->query('SELECT * FROM dining_tables ORDER BY active DESC, sort_order, name')->fetchAll(); $activeDiningTables=array_values(array_filter($diningTables, fn($t)=>(int)$t['active']===1)); $roles=db()->query('SELECT * FROM roles ORDER BY active DESC, sort_order, name')->fetchAll(); $activeRoles=array_values(array_filter($roles, fn($r)=>(int)$r['active']===1)); $systemUsers=db()->query('SELECT id, username, name, role, active, created_at FROM users ORDER BY active DESC, name')->fetchAll(); $allowedRoutes=role_routes($_SESSION['antojos_user']['role'] ?? 'mesero'); $canSeeFinanceGlobal=in_array('sales',$allowedRoutes,true)||in_array('reports',$allowedRoutes,true)||is_admin(); $appTheme=setting('app_theme','dark'); if(!in_array($appTheme,['dark','light'],true)){$appTheme='dark';} $today=date('Y-m-d'); $todaySales=db()->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE DATE(created_at)=CURDATE() AND status='pagado'")->fetchColumn(); $todayExpenses=db()->query("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE expense_date=CURDATE()")->fetchColumn(); $todayPurchases=db()->query("SELECT COALESCE(SUM(amount),0) FROM purchases WHERE purchase_date=CURDATE()")->fetchColumn(); $todayOrders=db()->query("SELECT COUNT(*) FROM orders WHERE DATE(created_at)=CURDATE()")->fetchColumn(); $todayProfit=(float)$todaySales-(float)$todayExpenses-(float)$todayPurchases; $todayAvgTicket=(int)$todayOrders>0?(float)$todaySales/(int)$todayOrders:0; $lastLiquidationEnd=db()->query("SELECT COALESCE(MAX(period_end), '1970-01-01 00:00:00') FROM liquidations")->fetchColumn(); $currentSales=(float)db()->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status='pagado' AND created_at > " . db()->quote($lastLiquidationEnd))->fetchColumn(); $currentExpenses=(float)db()->query("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE CONCAT(expense_date,' 23:59:59') > " . db()->quote($lastLiquidationEnd))->fetchColumn(); $currentPurchases=(float)db()->query("SELECT COALESCE(SUM(amount),0) FROM purchases WHERE CONCAT(purchase_date,' 23:59:59') > " . db()->quote($lastLiquidationEnd))->fetchColumn(); $currentProfit=$currentSales-$currentExpenses-$currentPurchases; $currentPeriodStart=date('Y-m-d', strtotime($lastLiquidationEnd . ' +1 second')); $currentPeriodLabel=$currentPeriodStart . ' a ' . $today; $recentLiquidations=db()->query('SELECT * FROM liquidations ORDER BY id DESC LIMIT 5')->fetchAll(); $recentOrders=db()->query('SELECT * FROM orders ORDER BY id DESC LIMIT 8')->fetchAll(); $dailyRows=db()->query("SELECT d.day,COALESCE(v.sales,0) sales,COALESCE(g.expenses,0) expenses,COALESCE(c.purchases,0) purchases FROM (SELECT CURDATE()-INTERVAL n DAY day FROM (SELECT 0 n UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6) x) d LEFT JOIN (SELECT DATE(created_at) day,SUM(total) sales FROM orders WHERE status='pagado' GROUP BY DATE(created_at)) v ON v.day=d.day LEFT JOIN (SELECT expense_date day,SUM(amount) expenses FROM expenses GROUP BY expense_date) g ON g.day=d.day LEFT JOIN (SELECT purchase_date day,SUM(amount) purchases FROM purchases GROUP BY purchase_date) c ON c.day=d.day ORDER BY d.day")->fetchAll(); $topProducts=db()->query("SELECT oi.product_name, SUM(oi.quantity) qty, SUM(oi.line_total) total FROM order_items oi INNER JOIN orders o ON o.id=oi.order_id WHERE o.status='pagado' AND o.created_at >= CURDATE()-INTERVAL 6 DAY GROUP BY oi.product_name ORDER BY qty DESC,total DESC LIMIT 5")->fetchAll(); $weekSales=array_sum(array_map(fn($d)=>(float)$d['sales'],$dailyRows)); $weekExpenses=array_sum(array_map(fn($d)=>(float)$d['expenses']+(float)$d['purchases'],$dailyRows)); $weekProfit=$weekSales-$weekExpenses; ?>
