g><?php echo money($a['price']); ?></strong></button><?php endforeach; ?></div><small class="text-muted d-block mt-2">Toca una adicion para marcarla, luego toca el producto. Se limpia automaticamente despues de agregar.</small></div></div><?php endif; ?></div><div class="col-lg-5"><div class="panel"><div class="panel-header"><strong>Pedido actual</strong></div><div class="panel-body"><label class="form-label">Cliente</label><input class="form-control mb-2" name="customer_name" placeholder="Nombre del cliente"><label class="form-label">Destino del pedido</label><div class="destination-toggle mb-2"><label><input type="radio" name="order_type" value="mesa" checked><span><i class="bi bi-grid-3x3-gap"></i> Mesa</span></label><label><input type="radio" name="order_type" value="recoger"><span><i class="bi bi-bag-check"></i> Recoger</span></label><label><input type="radio" name="order_type" value="domicilio"><span><i class="bi bi-geo-alt"></i> Domicilio</span></label></div><div class="mb-2" id="tableNameField"><label class="form-label mb-1" for="tableNameSelect">Mesa</label><select class="form-select" name="table_name" id="tableNameSelect"><?php foreach($activeDiningTables as $table): ?><option value="<?php echo e($table['name']); ?>"><?php echo e($table['name']); ?></option><?php endforeach; ?></select></div><small class="text-muted d-block mb-2" id="orderDestinationHelp">El ticket imprimira la mesa seleccionada.</small><label class="form-label">Fecha y hora de venta</label><div class="row g-2 mb-2"><div class="col-sm-7"><input class="form-control" type="date" name="sale_date" aria-label="Fecha de venta" value="<?php echo date('Y-m-d'); ?>"></div><div class="col-sm-5"><input class="form-control" type="time" name="sale_time" aria-label="Hora de venta" value="<?php echo date('H:i'); ?>"></div></div><small class="text-muted d-block mb-2">Puedes cambiarla para registrar ventas de dias anteriores.</small><div class="table-responsive"><table class="table cart-table"><thead><tr><th>Producto</th><th>Cant.</th><th class="text-end">Total</th><th></th></tr></thead><tbody id="cartBody"><tr><td colspan="4" class="text-muted text-center">Agrega productos</td></tr></tbody></table></div><label class="form-label">Descuento</label><input class="form-control mb-2" type="number" min="0" step="100" name="discount" id="discount" value="0"><label class="form-label">Medio de pago</label><select class="form-select mb-2" name="payment_method"><option value="efectivo">Efectivo</option><option value="nequi">Nequi</option><option value="daviplata">Daviplata</option><option value="transferencia">Transferencia</option><option value="tarjeta">Tarjeta</option></select><textarea class="form-control mb-3" name="notes" rows="2" placeholder="Notas del pedido"></textarea><div class="d-flex justify-content-between fs-5 mb-3"><strong>Total</strong><strong id="cartTotal">$0</strong></div><button class="btn btn-danger btn-lg w-100"><i class="bi bi-printer"></i> Cobrar e imprimir ticket</button></div></div></div></div></form><div class="panel mt-3"><div class="panel-header"><strong>Mesas parametrizables</strong><span class="text-muted small">Se usan en el ticket</span></div><div class="panel-body"><form method="post" class="row g-2 align-items-end mb-3"><input type="hidden" name="action" value="save_dining_table"><div class="col-md-5"><label class="form-label">Nueva mesa</label><input class="form-control" name="name" placeholder="Ej: Mesa 7, Barra, Terraza"></div><div class="col-md-3"><label class="form-label">Orden</label><input class="form-control" type="number" name="sort_order" value="100"></div><div class="col-md-2"><button class="btn btn-danger w-100"><i class="bi bi-plus-circle"></i> Agregar</button></div></form><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Mesa</th><th class="text-end">Orden</th><th>Estado</th><th class="text-end">Acciones</th></tr></thead><tbody><?php foreach($diningTables as $table): ?><tr><td><form method="post" class="table-edit-form"><input type="hidden" name="action" value="save_dining_table"><input type="hidden" name="id" value="<?php echo $table['id']; ?>"><input type="hidden" name="active" value="<?php echo (int)$table['active']; ?>"><input class="form-control form-control-sm" name="name" value="<?php echo e($table['name']); ?>"></td><td class="text-end"><input class="form-control form-control-sm table-order-input" type="number" name="sort_order" value="<?php echo (int)$table['sort_order']; ?>"></td><td><?php echo (int)$table['active']===1?'<span class="badge text-bg-success">Activa</span>':'<span class="badge text-bg-secondary">Inactiva</span>'; ?></td><td class="text-end text-nowrap"><button class="btn btn-sm btn-outline-primary"><i class="bi bi-save"></i></button></form><form method="post" class="d-inline"><input type="hidden" name="action" value="toggle_dining_table"><input type="hidden" name="id" value="<?php echo $table['id']; ?>"><button class="btn btn-sm btn-outline-warning"><i class="bi bi-power"></i></button></form></td></tr><?php endforeach; ?></tbody></table><?php if(!$diningTables): ?><div class="text-muted text-center py-3">Aun no hay mesas configuradas.</div><?php endif; ?></div></div></div>
<?php elseif ($route==='sales'):
$from=$_GET['from'] ?? date('Y-m-d', strtotime('-7 days'));
$to=$_GET['to'] ?? date('Y-m-d');
$method=$_GET['method'] ?? '';
$search=trim($_GET['q'] ?? '');
if ($from > $to) { [$from,$to]=[$to,$from]; }
$where="WHERE o.status='pagado' AND DATE(o.created_at) BETWEEN ? AND ?";
$params=[$from,$to];
if($method!==''){ $where.=' AND o.payment_method=?'; $params[]=$method; }
if($search!==''){ $where.=' AND (o.order_number LIKE ? OR o.customer_name LIKE ? OR o.notes LIKE ?)'; $like='%'.$search.'%'; array_push($params,$like,$like,$like); }
$stmt=db()->prepare("SELECT o.*, COALESCE(SUM(oi.quantity),0) item_qty, COALESCE(SUM(oi.line_total - (oi.quantity*oi.unit_cost)),0) margin_est FROM orders o LEFT JOIN order_items oi ON oi.order_id=o.id $where GROUP BY o.id ORDER BY o.created_at DESC, o.id DESC LIMIT 300");
$stmt->execute($params);
$sales=$stmt->fetchAll();
$orderIds=array_column($sales,'id');
$itemsByOrder=[]; $addonsByItem=[];
if($orderIds){ $in=implode(',',array_fill(0,count($orderIds),'?')); $it=db()->prepare("SELECT * FROM order_items WHERE order_id IN ($in) ORDER BY id"); $it->execute($orderIds); $itemIds=[]; foreach($it->fetchAll() as $item){ $itemsByOrder[$item['order_id']][]=$item; $itemIds[]=$item['id']; } if($itemIds){ $inItems=implode(',',array_fill(0,count($itemIds),'?')); $ad=db()->prepare("SELECT * FROM order_item_addons WHERE order_item_id IN ($inItems) ORDER BY id"); $ad->execute($itemIds); foreach($ad->fetchAll() as $addon){ $addonsByItem[$addon['order_item_id']][]=$addon; } } }
$rangeTotal=array_sum(array_map(fn($s)=>(float)$s['total'],$sales));
$rangeDiscount=array_sum(array_map(fn($s)=>(float)$s['discount'],$sales));
$rangeMargin=array_sum(array_map(fn($s)=>(float)$s['margin_est'],$sales));
$rangeCount=count($sales);
$avgTicket=$rangeCount?($rangeTotal/$rangeCount):0;
$paySummary=[]; $salesByDay=[];
$cursor=new DateTime($from); $endDt=new DateTime($to); while($cursor <= $endDt){ $salesByDay[$cursor->format('Y-m-d')]=['day'=>$cursor->format('Y-m-d'),'sales'=>0,'orders'=>0,'margin'=>0]; $cursor->modify('+1 day'); }
foreach($sales as $sale){ $m=$sale['payment_method'] ?: 'sin metodo'; if(!isset($paySummary[$m])){$paySummary[$m]=['method'=>$m,'qty'=>0,'total'=>0];} $paySummary[$m]['qty']++; $paySummary[$m]['total']+=(float)$sale['total']; $d=substr((string)$sale['created_at'],0,10); if(!isset($salesByDay[$d])){$salesByDay[$d]=['day'=>$d,'sales'=>0,'orders'=>0,'margin'=>0];} $salesByDay[$d]['sales']+=(float)$sale['total']; $salesByDay[$d]['orders']++; $salesByDay[$d]['margin']+=(float)$sale['margin_est']; }
$salesChartRows=array_values($salesByDay); usort($salesChartRows, fn($a,$b)=>strcmp($a['day'],$b['day']));
$salesPaymentRows=array_values($paySummary); usort($salesPaymentRows, fn($a,$b)=>$b['total']<=>$a['total']);
$methods=db()->query("SELECT DISTINCT payment_method FROM orders WHERE payment_method<>'' ORDER BY payment_method")->fetchAll();
$bestPayment=$salesPaymentRows[0]??null; $bestDay=null; foreach($salesChartRows as $row){ if(!$bestDay || (float)$row['sales']>(float)$bestDay['sales']){$bestDay=$row;} }
?>
