$reportMode = $_GET['mode'] ?? 'day';
$fromDate = $_GET['day'] ?? date('Y-m-d');
$toDate = $fromDate;
$reportTitle = 'Reporte diario';
if ($reportMode === 'week') { $week = $_GET['week'] ?? date('o-\WW'); if(preg_match('/^(\d{4})-W(\d{2})$/',$week,$m)){ $dt=new DateTime(); $dt->setISODate((int)$m[1],(int)$m[2]); $fromDate=$dt->format('Y-m-d'); $dt->modify('+6 days'); $toDate=$dt->format('Y-m-d'); $reportTitle='Reporte semanal '.e($week); } }
elseif ($reportMode === 'month') { $month=$_GET['month'] ?? date('Y-m'); $dt=DateTime::createFromFormat('Y-m-d',$month.'-01')?:new DateTime('first day of this month'); $fromDate=$dt->format('Y-m-01'); $toDate=$dt->format('Y-m-t'); $reportTitle='Reporte mensual '.e($month); }
elseif ($reportMode === 'range') { $fromDate=$_GET['from'] ?? date('Y-m-d', strtotime('-14 days')); $toDate=$_GET['to'] ?? date('Y-m-d'); if($fromDate>$toDate){[$fromDate,$toDate]=[$toDate,$fromDate];} $reportTitle='Reporte por rango'; }
else { $reportMode='day'; }
$fromDT=$fromDate.' 00:00:00'; $toDT=$toDate.' 23:59:59'; $pdo=db();
$stmt=$pdo->prepare("SELECT COUNT(*) orders_count, COALESCE(SUM(total),0) sales_total, COALESCE(AVG(total),0) avg_ticket, COALESCE(SUM(discount),0) discounts FROM orders WHERE status='pagado' AND created_at BETWEEN ? AND ?");
$stmt->execute([$fromDT,$toDT]); $reportSales=$stmt->fetch();
$stmt=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE expense_date BETWEEN ? AND ?"); $stmt->execute([$fromDate,$toDate]); $reportExpenses=(float)$stmt->fetchColumn();
$stmt=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM purchases WHERE purchase_date BETWEEN ? AND ?"); $stmt->execute([$fromDate,$toDate]); $reportPurchases=(float)$stmt->fetchColumn();
$reportRevenue=(float)$reportSales['sales_total']; $reportCosts=$reportExpenses+$reportPurchases; $reportNet=$reportRevenue-$reportCosts; $reportMarginPct=$reportRevenue>0?($reportNet/$reportRevenue)*100:0;
$stmt=$pdo->prepare("SELECT oi.product_name, SUM(oi.quantity) qty, SUM(oi.line_total) total, SUM(oi.line_total-(oi.quantity*oi.unit_cost)) margin FROM order_items oi INNER JOIN orders o ON o.id=oi.order_id WHERE o.status='pagado' AND o.created_at BETWEEN ? AND ? GROUP BY oi.product_name ORDER BY total DESC, qty DESC LIMIT 12"); $stmt->execute([$fromDT,$toDT]); $reportProducts=$stmt->fetchAll();
