ows ?? [],"averageProductRows"=>$averageProductRows ?? [],"averageDailyRows"=>$averageDailyRows ?? [],"averageHourRows"=>$averageHourRows ?? []], JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT); ?></script><script src="assets/app.js?v=20260709a"></script></body></html>

